   //helepr to get expression type
   String getExpressionType(Expression e){
      if(e.f0.which==9){
         PostfixExpression p=(PostfixExpression)e.f0.choice;
         if(p.f0.which==2){
            MessageSend m=(MessageSend)p.f0.choice;
            String recieverType=getRecieverType(m.f0);
            String methodName=(String)m.f2.accept(this,null);
            MethodInfo method=getMethodInfo(recieverType, methodName);
            if(method!=null){
               return method.returnType;
            }
         }
         if(p.f0.which==3){
            PrimaryExpression primary=(PrimaryExpression)p.f0.choice;
            return getRecieverType(primary);
         }
      }
      return null;
   }
   //helper to get reciever type
   String getRecieverType(PrimaryExpression p){
      if(p.f0.which==3){
         String name=(String)p.f0.accept(this,null);
         return getVariableTypes(name);
      }
      if(p.f0.which==4){
         return currentClass;
      }
      if(p.f0.which==6){
         AllocationExpression a=(AllocationExpression)p.f0.choice;
         return (String)a.f1.accept(this,null);
      }
      if(p.f0.which==7){
         BracketExpression b=(BracketExpression)p.f0.choice;
         return getExpressionType(b.f1);
      }
      return null;
   }
