   //helper to build MethodOrder
   void buildMethodOrder(String className, ArrayList<String>order){
      ClassInfo c=classes.get(className);
      if(c==null){
         return;
      }
      if(c.parent!=null){
         buildMethodOrder(c.parent, order);
      }
      for(String method: c.methodOrder){
         if(!order.contains(method)){
            order.add(method);
         }
      }
   }
   //helper to get method implementation
   String getMethodImplementation(String className, String methodName){
      ClassInfo c=classes.get(className);
      while(c!=null){
         if(c.methods.containsKey(methodName)){
            return c.name+"_"+methodName;
         }
         if(c.parent==null){
            break;
         }
         c=classes.get(c.parent);
      }
      return null;
   }
   //helper for vmt genration
   void emitVTables(){
      for(String className: classes.keySet()){
         if( className.equals("Main")){
            continue;
         }
         ArrayList<String>methods=getAllMethods(className);
         int size=methods.size()*4;
         int vmtTemp=newTemp();
         vmtTemps.put(className,vmtTemp);
         emit("MOVE TEMP "+vmtTemp+" HALLOCATE "+size);
         int offset=0;
         for(String method:methods){
            String implementation=getMethodImplementation(className, method);
            emit("HSTORE TEMP "+vmtTemp+" "+offset+" "+implementation);
            offset=offset+4;
         }
      }
   }
   //helper to get all methods
   ArrayList<String> getAllMethods(String className){
      ArrayList<String>result=new ArrayList<String>();
      buildMethodOrder(className, result);
      return result;
   }

