      emit("MOVE TEMP "+idxTemp+" 4");
      emitLabel(zeroStart);
      emit("CJUMP LE TEMP "+idxTemp+" TIMES "+size+" 4 "+zeroEnd);
      emit("HSTORE PLUS TEMP "+arrayTemp+" TEMP "+idxTemp+" 0 0");
