   /**
    * f0 -> "new"
    * f1 -> Identifier()
    * f2 -> "("
    * f3 -> ")"
    */
   public R visit(AllocationExpression n, A argu) {
		/* YOUR CODE HERE */

      /*R _ret=null;
      n.f0.accept(this, argu);
      n.f1.accept(this, argu);
      n.f2.accept(this, argu);
      n.f3.accept(this, argu);
      return _ret;*/
      String className=(String)n.f1.accept(this,argu);
      int size=getObjectSize(className);
      int objectTemp=newTemp();
      emit("MOVE TEMP "+objectTemp+" HALLOCATE "+size);
      ArrayList<String>methods=getAllMethods(className);
      int vmtSize=methods.size()*4;
      int vmtTemp=newTemp();
      emit("MOVE TEMP "+vmtTemp+" HALLOCATE "+vmtSize);
      int offset=0;
      for(String method:methods){
         String implementation=getMethodImplementation(className, method);
         emit("HSTORE TEMP "+vmtTemp+" "+offset+" "+implementation);
         offset=offset+4;
      }
      emit("HSTORE TEMP "+objectTemp+" 0 TEMP "+vmtTemp);
      for(int fieldOffset=4; fieldOffset<size; fieldOffset=fieldOffset+4){
         emit("HSTORE TEMP "+objectTemp+" "+fieldOffset+" 0");
      }
      return(R)("TEMP "+objectTemp);
   }

